KG42.register("rules-b59a8ac3d61faf5ba0234193",{"id":"01-central_pool::v141-c-R004","paper":"01-central_pool","record":{"rule_id":"v141-c-R004","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"Local market clearing determines the executed energy-exchange quantities. Scope: Executed energy-exchange quantities in the lower-level community microgrid market-clearing problem. Each entity's energy exchanges with the community are valued at its local market-clearing price for the corresponding time period. Scope: Internal community energy exchanges for each entity u at time t. Total energy imported from the community must equal total energy exported to the community in each time period. Scope: Internal energy-exchange quantities across all community entities at each modeled time period. An entity cannot simultaneously import energy from and export energy to the community. Scope: Internal community imports and exports by the same entity within the same time period. Condition: At an optimum of the lower-level problem, when the community operator's unitary fee is nonzero.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["clearing.local","execution.energy_trade","pricing.local"],"E":[{"edge_id":"v141-c-R004-E001","source":"clearing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R004-C001"],"evidence_ids":["v141-b-g01-e011"]},{"edge_id":"v141-c-R004-E002","source":"pricing.local","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R004-C002"],"evidence_ids":["v141-b-g02-E16"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Executed energy-exchange quantities in the lower-level community microgrid market-clearing problem. | Internal community energy exchanges for each entity u at time t. | Internal community imports and exports by the same entity within the same time period. | Internal energy-exchange quantities across all community entities at each modeled time period.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e011","v141-b-g02-E08","v141-b-g02-E11","v141-b-g02-E16","v141-b-g03-e30"]},"x":[{"variable_id":"v141-c-R004-e-com","symbol":"e_{u,t}^{com}","meaning":"Energy exported to the community at time period t by entity u; an executed internal community energy-exchange quantity determined by the lower-level market-clearing problem.","kind":"operational","domain":"e_{u,t}^{com} in R_+ (nonnegative real)","unit":"kWh","indices":["u in U (entity)","t in T (time period)"],"evidence_ids":["v141-b-g01-e029","v141-b-g02-E08","v141-b-g02-E16"]},{"variable_id":"v141-c-R004-i-com","symbol":"i_{u,t}^{com}","meaning":"Energy imported from the community at time period t by entity u; an executed internal community energy-exchange quantity determined by the lower-level market-clearing problem.","kind":"operational","domain":"i_{u,t}^{com} in R_+ (nonnegative real)","unit":"kWh","indices":["u in U (entity)","t in T (time period)"],"evidence_ids":["v141-b-g01-e029","v141-b-g02-E08","v141-b-g02-E16"]},{"variable_id":"v141-c-R004-pi-com","symbol":"pi_{u,t}^{com}","meaning":"Local market-clearing price at which entity u exchanges energy with the community at time period t; dual variable of the entity energy-balance constraint (11), determined by the lower-level clearing within the marginal-pricing framework. Its unit is not stated in the source Nomenclature.","kind":"operational","domain":"pi_{u,t}^{com} in R (real)","unit":null,"indices":["u in U (entity)","t in T (time period)"],"evidence_ids":["v141-b-g01-e025","v141-b-g01-e029","v141-b-g02-E16"]}],"theta":[{"parameter_id":"v141-c-R004-gamma-com","symbol":"gamma^{com}","meaning":"Unitary fee of the community microgrid operator applied to internal community energy exchanges; the no-simultaneous-community-import/export property (C004) holds when it is nonzero.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"EUR/kWh","indices":[],"evidence_ids":["v141-b-g01-e007","v141-b-g01-e028","v141-b-g03-e30"]}],"phi":[{"constraint_id":"v141-c-R004-C001","kind":"procedural","role":"core","statement":"Local market clearing determines the executed energy-exchange quantities. Scope: Executed energy-exchange quantities in the lower-level community microgrid market-clearing problem.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.local","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e011","v141-b-g02-E35"]},{"constraint_id":"v141-c-R004-C002","kind":"mathematical","role":"core","statement":"Each entity's energy exchanges with the community are valued at its local market-clearing price for the corresponding time period. Scope: Internal community energy exchanges for each entity u at time t.","expression":"-\\pi_{u,t}^{com} \\left( e_{u,t}^{com} - i_{u,t}^{com} \\right)","formalization_origin":"source","template_id":null,"members":["pricing.local","execution.energy_trade"],"variable_refs":["v141-c-R004-e-com","v141-c-R004-i-com","v141-c-R004-pi-com"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E16","v141-b-g01-e025"]},{"constraint_id":"v141-c-R004-C003","kind":"mathematical","role":"core","statement":"Total energy imported from the community must equal total energy exported to the community in each time period. Scope: Internal energy-exchange quantities across all community entities at each modeled time period.","expression":"\\sum_{u \\in \\mathcal{U}} \\left( i_{u,t}^{com} - e_{u,t}^{com} \\right) = 0, \\quad \\forall t \\in \\mathcal{T}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R004-e-com","v141-c-R004-i-com"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E08","v141-b-g01-e022"]},{"constraint_id":"v141-c-R004-C004","kind":"mathematical","role":"core","statement":"An entity cannot simultaneously import energy from and export energy to the community. Scope: Internal community imports and exports by the same entity within the same time period. Condition: At an optimum of the lower-level problem, when the community operator's unitary fee is nonzero.","expression":"\\neg \\left( e_{u,t}^{com} > 0 \\; \\wedge \\; i_{u,t}^{com} > 0 \\right), \\quad \\forall u \\in \\mathcal{U}, \\forall t \\in \\mathcal{T}","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R004-e-com","v141-c-R004-i-com"],"parameter_refs":["v141-c-R004-gamma-com"],"evidence_ids":["v141-b-g02-E11","v141-b-g03-e30","v141-b-g01-e026"]}],"pi":[{"evidence_id":"v141-b-g01-e011","location":{"location_id":"src-13c261d954-p04-c2r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"3.1. The bilevel model","anchor_text":"th level objective functions are different, and represent conflicting inter- n- ests. Conversely, in","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Conversely, in power system economics [29-32], bilevel programming is typically used to access dual variables, which represent market prices within the marginal pricing framework [21]. This is the main reason to adopt a bilevel formulation in this paper. In the proposed bilevel model, the lower level solves the community microgrid market clearing problem, by determining: the executed quantities, the community prices, the community symmetric reserve, and the community peak power, with the aim of maximizing the social welfare of the community."},{"evidence_id":"v141-b-g02-E08","location":{"location_id":"src-13c261d954-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1.1","anchor_text":"eugri, t i ugri, t + eucom, t i ucom, t nst ste ste3) T Pd, t + ad, t Pd, t u y, d unst d ste n- at ","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Σ_{u∈U} ( i_{u,t}^com - e_{u,t}^com ) = 0, ∀t ∈ T [μ_t ∈ R] (12) Constraint (12) imposes the balance of the energy flows within the community at each time period."},{"evidence_id":"v141-b-g02-E11","location":{"location_id":"src-13c261d954-p05-c2r4__v141-a-M01-validation","page":5,"printed_page":null,"section":"3.1.1","anchor_text":"limits to the net energy exported to and imported from the grid by eachrd entity at each time period","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Remark 1. At the optimum of the lower level problem, e_{u,t}^gri and i_{u,t}^gri, as well as e_{u,t}^com and i_{u,t}^com, cannot be simultaneously greater than 0. In other words, no simultaneous export to and import from the grid can occur for entity u over a given time period. The same holds for the energy exported to and imported from the community by entity u. Both results are shown in C.2."},{"evidence_id":"v141-b-g02-E16","location":{"location_id":"src-13c261d954-p06-c2r2__v141-a-M01-coordination","page":6,"printed_page":null,"section":"3.1.2","anchor_text":"ce u u u u ( ) nd be the total profit of entity u within the considered community mi- crogrid framew","equation_id":"(26)-(27)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"we let J_u = J_u^energy + J_u^reserve + J_u^peak (26) be the total profit of entity u within the considered community microgrid framework. In (26), the quantity J_u^energy takes into account the revenues and costs for entity u related to energy flows: J_u^energy = - Σ_{t∈T} ( Σ_{d∈D_u^she} π_{d,t}^she C_{d,t}^she Δ_τ a_{d,t}^she + Σ_{d∈D_u^ste} π_{d,t}^ste P_{d,t}^ste Δ_τ a_{d,t}^ste - π_t^egr e_{u,t}^gri + π_t^igr i_{u,t}^gri - π_{u,t}^com ( e_{u,t}^com - i_{u,t}^com ) + Σ_{d∈D_u^sto} γ_d^sto Δ_τ ( P̄_d η_d^cha a_{d,t}^cha + P̲_d/η_d^dis a_{d,t}^dis ) ). (27) Notice that the energy exchanges with the community, e_{u,t}^com and i_{u,t}^com, are valued at the price π_{u,t}^com, i.e., the market-clearing price for entity u at time t."},{"evidence_id":"v141-b-g03-e30","location":{"location_id":"src-13c261d954-p13-c1r3__v141-a-M01-validation","page":13,"printed_page":"559","section":"Appendix C.2","anchor_text":"= eu , t µ t com i u , t µt + com t u t u = µt eucom, t i ucom, t com e ucom, t + i ucom, t t u u t ","equation_id":"(C.3), (C.4)","figure_id":null,"table_id":null,"image_ref":"pages/page-13.png","occurrence_role":"condition"},"source_text":"This section shows that no simultaneous import from or export to the grid is possible by the same entity at the same time, as long as \\pi_t^{egr} != \\pi_t^{igr}.\nIndeed, from the dual constraints (A.9) and (A.10), due to the complementary slackness conditions, the following hold:\n\nif e_{u,t}^{gri} > 0 then \\pi_{u,t}^{com} - \\frac{\\varphi_t^{peak}}{\\Delta_\\tau} + \\frac{\\varphi_{u,t}^{eCap} - \\varphi_{u,t}^{iCap}}{\\Delta_\\tau} = \\pi_t^{egr}   (C.3)\n\nif i_{u,t}^{gri} > 0 then \\pi_{u,t}^{com} - \\frac{\\varphi_t^{peak}}{\\Delta_\\tau} + \\frac{\\varphi_{u,t}^{eCap} - \\varphi_{u,t}^{iCap}}{\\Delta_\\tau} = \\pi_t^{igr}.   (C.4)\n\nThen, if \\pi_t^{egr} != \\pi_t^{igr}, the conditions (C.3) and (C.4) cannot hold simultaneously. Therefore, the variables e_{u,t}^{gri} and i_{u,t}^{gri} cannot be both strictly positive at the same time. Notice that, for similar considerations on the conditions (C.1) and (C.2), as long as \\gamma^{com} != 0, it is not even possible to have simultaneous import from and export to the community by the same entity."},{"evidence_id":"v141-b-g01-e007","location":{"location_id":"src-13c261d954-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":null,"section":"2. The community microgrid architecture","anchor_text":"operationalplanning stage that optimizes day-ahead decisions with le time periods of T hours, given ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"To achieve the aforementioned benefits, this paper focuses on the operational planning stage that optimizes day-ahead decisions with time periods of $\\Delta_T$ hours, given the grid energy prices, and the consumption and generation forecasts of the entities. An operator manages the community to maximize its social welfare, by optimizing the energy flows and the interactions among the entities and with the public grid. The operator must be contractually bound to the DSO, and its perimeter must be clearly defined. It must also be trusted by, and be contractually bound to, the community entities. The latter pay a fee to the operator for the remuneration of its activity."},{"evidence_id":"v141-b-g01-e022","location":{"location_id":"src-13c261d954-p05-c2r2__v141-a-M01-clearing","page":5,"printed_page":null,"section":"3.1.1. Lower level problem","anchor_text":"eugri, t i ugri, t + eucom, t i ucom, t nst ste ste3) T Pd, t + ad, t Pd, t u y, d unst d ste n- at ","equation_id":"(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"$\\sum_{u \\in \\mathcal{U}} \\left( i_{u,t}^{com} - e_{u,t}^{com} \\right) = 0 \\quad \\forall t \\in \\mathcal{T} \\quad [\\mu_t \\in \\mathbb{R}]$  (12)\nConstraint (12) imposes the balance of the energy flows within the community at each time period."},{"evidence_id":"v141-b-g01-e025","location":{"location_id":"src-13c261d954-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"3.1.1. Lower level problem","anchor_text":"( i ugri, t e ugri, t )/ T p t . t peak 0 u (15) Constraint (11) defines the energy balance for each","equation_id":"(11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"It is stressed that the dual variable $\\pi_{u,t}^{com}$ of constraint (11) has an important economic interpretation within the marginal pricing framework [21,22]. Indeed, being $\\pi_{u,t}^{com}$ the dual variable of the energy balance constraint for entity u, in the proposed formulation it represents the market price at which entity u exchanges energy with the community at time t [33]."},{"evidence_id":"v141-b-g01-e026","location":{"location_id":"src-13c261d954-p05-c2r4__v141-a-M01-validation","page":5,"printed_page":null,"section":"3.1.1. Lower level problem","anchor_text":"limits to the net energy exported to and imported from the grid by eachrd entity at each time period","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Remark 1. At the optimum of the lower level problem, $e_{u,t}^{gri}$ and $i_{u,t}^{gri}$, as well as $e_{u,t}^{com}$ and $i_{u,t}^{com}$, cannot be simultaneously greater than 0. In other words, no simultaneous export to and import from the grid can occur for entity u over a given time period. The same holds for the energy exported to and imported from the community by entity u. Both results are shown in C.2."},{"evidence_id":"v141-b-g01-e028","location":{"location_id":"src-13c261d954-p02-c1r3__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"d t,l p p p , s d she, kW rd Eucapt, maximum power export to the grid at time period t, with u , kW ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Parameters\n$C_{d,t}^{nfl}$ non-flexible power consumption at time period t, with $d \\in \\mathcal{D}^{nfl}$, kW\n$C_{d,t}^{she}$ flexible power consumption at time period t, with $d \\in \\mathcal{D}^{she}$, kW\n$E_{u,t}^{cap}$ maximum power export to the grid at time period t, with $u \\in \\mathcal{U}$, kW\n$I_{u,t}^{cap}$ maximum power import from the grid at time period t, with $u \\in \\mathcal{U}$, kW\n$P_{d,t}^{nst}$ non-steerable power generation at time period t, with $d \\in \\mathcal{D}^{nst}$, kW\n$P_{d,t}^{ste}$ steerable power generation at time period t, with $d \\in \\mathcal{D}^{ste}$, kW\n$\\bar{P}_d$ maximum charging power of battery d, with $d \\in \\mathcal{D}^{sto}$, kW\n$\\underline{P}_d$ maximum discharging power of battery d, with $d \\in \\mathcal{D}^{sto}$, kW\n$\\bar{S}_d$ maximum capacity of battery d, with $d \\in \\mathcal{D}^{sto}$, kWh\n$\\underline{S}_d$ minimum capacity of battery d, with $d \\in \\mathcal{D}^{sto}$, kWh\n$S_d^{init}$ initial state of charge of battery d, with $d \\in \\mathcal{D}^{sto}$, kWh\n$S_d^{end}$ final state of charge of battery d, with $d \\in \\mathcal{D}^{sto}$, kWh\n$J_u^{SU}$ optimal profit of entity u acting individually, €\n$\\gamma_d^{sto}$ unitary cost for usage of battery d, with $d \\in \\mathcal{D}^{sto}$, €/kWh\n$\\gamma^{com}$ unitary fee of the community microgrid operator, €/kWh\n$\\eta_d^{cha}$ charging efficiency of battery d, with $d \\in \\mathcal{D}^{sto}$\n$\\eta_d^{dis}$ discharging efficiency of battery d, with $d \\in \\mathcal{D}^{sto}$\n$\\pi^{peak}$ unitary cost (penalty) for peak power, €/kW\n$\\pi^{res}$ unitary revenue for providing reserve capacity, €/kW\n$\\pi_{d,t}^{she}$ unitary cost of load shedding at time period t, with $d \\in \\mathcal{D}^{she}$, €/kWh\n$\\pi_{d,t}^{ste}$ unitary cost of generating energy at time period t, with $d \\in \\mathcal{D}^{ste}$, €/kWh\n$\\pi_t^{egr}$ unit price of energy exported to the grid at time period t, €/kWh\n$\\pi_t^{igr}$ unit price of energy imported from the grid at time period t, €/kWh\n$\\Delta_T$ duration of a time period, h"},{"evidence_id":"v141-b-g01-e029","location":{"location_id":"src-13c261d954-p02-c2r2__v141-a-M01-clearing","page":2,"printed_page":null,"section":"Nomenclature","anchor_text":"eucomt, + energy exported to the community at time period t by entity u , kWh eugrit, + energy expor","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Variables\n$\\alpha$ + slack variable to be maximized, €\n$\\alpha_{d,t}^{she}$ [0, 1] fraction of flexible power consumption that is shed at time period t, with $d \\in \\mathcal{D}^{she}$\n$\\alpha_{d,t}^{ste}$ [0, 1] fraction of steerable power generation that is activated at time period t, with $d \\in \\mathcal{D}^{ste}$\n$\\alpha_{d,t}^{cha}$ [0, 1] fraction of the maximum charging power used for battery d at time period t, with $d \\in \\mathcal{D}^{sto}$\n$\\alpha_{d,t}^{dis}$ [0, 1] fraction of the maximum discharging power used for battery d at time period t, with $d \\in \\mathcal{D}^{sto}$\n$e_{u,t}^{com}$ R_+ energy exported to the community at time period t by entity u, kWh\n$e_{u,t}^{gri}$ R_+ energy exported to the grid at time period t by entity u, kWh\n$i_{u,t}^{com}$ R_+ energy imported from the community at time period t by entity u, kWh\n$i_{u,t}^{gri}$ R_+ energy imported from the grid at time period t by entity u, kWh\n$\\bar{p}$ R_+ peak power of the microgrid over the planning horizon T, kW\n$\\bar{p}_u$ R_+ contribution to the peak power of the microgrid assigned to entity u, kW\n$r^{sym}$ R_+ symmetric power reserve provided by the microgrid through all periods of the planning horizon T, kW\n$r_u^{sym}$ R_+ contribution to the symmetric power reserve of the microgrid assigned to entity u, kW\n$r_{u,t}^{inc}$ R_+ upward reserve of power available at time period t and provided by entity u, kW\n$r_{u,t}^{dec}$ R_ downward reserve of power available at time period t and provided by entity u, kW\n$r_{d,t}^{s+}$ R_+ upward reserve of power available at time period t and provided by storage device d, kW\n$r_{d,t}^{s-}$ R_ downward reserve of power available at time period t and provided by storage device d, kW\n$s_{d,t}$ [S̲_d, S̄_d] state of charge of battery d at time period t, with $d \\in \\mathcal{D}^{sto}$, kWh\n$J_u$ R total profit of entity u acting in the community, €\n$J_u^{energy}$ R energy component of the profit of entity u, €\n$J_u^{peak}$ R_ peak power component of the profit of entity u, €\n$J_u^{reserve}$ R_ reserve component of the profit of entity u, €\n$J^*$ R optimal profit of the community microgrid, €\n\nDual Variables, and Corresponding Constraints\n$\\kappa_{d,t}^{s+}/\\kappa_{d,t}^{s-}$ R_+ storage upward/downward reserve, state of charge\n$\\mu_t$ R community energy balance\n$\\pi_{u,t}^{com}$ R entity energy balance\n$\\varphi_t^{inc}/\\varphi_t^{dec}$ R_+ symmetric reserve, upward/downward reserve\n$\\zeta_{d,t}$ R dynamics of battery state of charge\n$\\varphi_{d,t}^{she}/\\varphi_{d,t}^{ste}$ R_+ maximum load shedding/steerable generation\n$\\varphi_{d,t}^{cha}/\\varphi_{d,t}^{dis}$ R_+ maximum storage charging/discharging\n$\\varphi_{d,t}^{socUp}/\\varphi_{d,t}^{socLo}$ R_+ maximum/minimum battery state of charge\n$\\varphi_{u,t}^{eCap}/\\varphi_{u,t}^{iCap}$ R_+ maximum energy export/import to/from the grid\n$\\varphi_t^{peak}$ R_+ community peak power\n$\\varphi_{d,t}^{s+}/\\varphi_{d,t}^{s-}$ R_+ storage upward/downward reserve, power\n$\\xi_d$ R final battery state of charge"},{"evidence_id":"v141-b-g02-E35","location":{"location_id":"src-13c261d954-p04-c2r3__v141-a-M01-clearing","page":4,"printed_page":null,"section":"3.1","anchor_text":"th level objective functions are different, and represent conflicting inter- n- ests. Conversely, in","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"In the proposed bilevel model, the lower level solves the community microgrid market clearing problem, by determining: the executed quantities, the community prices, the community symmetric reserve, and the community peak power, with the aim of maximizing the social welfare of the community. Then, the role of the upper level is to share among the entities the profits of the community, by ensuring that no entity is penalized with respect to acting individually."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e011","quote":"the lower level solves the community microgrid market clearing problem, by determining: the executed quantities"}],[{"evidence_id":"v141-b-g02-E16","quote":"Notice that the energy exchanges with the community, e_{u,t}^com and i_{u,t}^com, are valued at the price π_{u,t}^com, i.e., the market-clearing price for entity u at time t."}],[{"evidence_id":"v141-b-g02-E08","quote":"Σ_{u∈U} ( i_{u,t}^com - e_{u,t}^com ) = 0, ∀t ∈ T [μ_t ∈ R] (12) Constraint (12) imposes the balance of the energy flows within the community at each time period."}],[{"evidence_id":"v141-b-g02-E11","quote":"At the optimum of the lower level problem, e_{u,t}^gri and i_{u,t}^gri, as well as e_{u,t}^com and i_{u,t}^com, cannot be simultaneously greater than 0."},{"evidence_id":"v141-b-g03-e30","quote":"as long as \\gamma^{com} != 0, it is not even possible to have simultaneous import from and export to the community by the same entity."}]],"C2_formalization":{"graph_sha256":"8dd7ee0af61cf242fb448057466778c49f73cd578a1a9a36833c63f31cbafe38","applicability":"formalized","reason":"The R004 internal energy-trade execution rule has direct source support for three of its four constraints. C003 transcribes the community energy-balance equation (12); C004 transcribes the optimality condition that the same entity cannot simultaneously import from and export to the community (Remark 1 / Appendix C.2, conditional on the community operator's unitary fee being nonzero); and C002 transcribes the valuation of internal community exchanges at the entity- and time-indexed local clearing price as given by the community term of J_u^{energy}, eq. (27). C001 stays not_formalized because its evidence (v141-b-g01-e011) is prose stating that the lower level determines the executed quantities and contains no equation. The executed quantities e_{u,t}^{com} and i_{u,t}^{com} are lower-level operational decision variables (R_+, kWh), pi_{u,t}^{com} is the local market-clearing price (dual of the entity balance (11), R), and gamma^{com} is the operator-fee parameter (EUR/kWh) that conditions C004. The frozen graph represents all transcribed formulas through the existing nodes and edges, so no C.1 revision is requested. All referenced B evidence remains UNREVIEWED under the experimental policy; no independent source review has been performed and none is claimed.","bindings":[{"object_id":"v141-c-R004-e-com","node_ids":["execution.energy_trade"],"edge_ids":["v141-c-R004-E001"],"rationale":"e_{u,t}^{com} is an executed internal community energy-exchange quantity and thus belongs to the execution.energy_trade node; it is determined by the lower-level clearing (clearing.local), which is the relationship captured by edge E001 (clearing.local -> execution.energy_trade)."},{"object_id":"v141-c-R004-i-com","node_ids":["execution.energy_trade"],"edge_ids":["v141-c-R004-E001"],"rationale":"i_{u,t}^{com} is an executed internal community energy-exchange quantity belonging to execution.energy_trade; it is determined by the lower-level clearing, i.e., the relationship of edge E001 (clearing.local -> execution.energy_trade)."},{"object_id":"v141-c-R004-pi-com","node_ids":["pricing.local"],"edge_ids":["v141-c-R004-E002"],"rationale":"pi_{u,t}^{com} is the local market-clearing price (node pricing.local), the dual of the entity energy-balance constraint (11). Edge E002 (pricing.local -> execution.energy_trade) expresses that the executed internal exchanges are valued at this price."},{"object_id":"v141-c-R004-gamma-com","node_ids":["pricing.local","execution.energy_trade"],"edge_ids":["v141-c-R004-E002"],"rationale":"gamma^{com} is the operator's unitary fee on internal community exchanges; it enters the value of internal exchanges (execution.energy_trade) and shifts the local clearing price (pricing.local). Edge E002 (pricing.local -> execution.energy_trade) relates the two nodes for this fee."},{"object_id":"v141-c-R004-C002","node_ids":["pricing.local","execution.energy_trade"],"edge_ids":["v141-c-R004-E002"],"rationale":"C002 formalizes that executed internal community exchanges are valued at the local market-clearing price. Its members map to pricing.local and execution.energy_trade, linked by edge E002. The transcribed term -pi_{u,t}^{com}(e_{u,t}^{com} - i_{u,t}^{com}) is the community-exchange term appearing inside J_u^{energy}, eq. (27) (v141-b-g02-E16)."},{"object_id":"v141-c-R004-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"C003 is the community-level energy balance (12) among executed internal quantities; its sole member is execution.energy_trade. No frozen edge lists C003, and the balance does not require a directed edge between the other two nodes."},{"object_id":"v141-c-R004-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"C004 is the optimality property excluding simultaneous community import and export by the same entity (Remark 1 / Appendix C.2); its member is execution.energy_trade. The condition depends on the operator fee gamma^{com} (bound to pricing.local), but no frozen edge lists C004."}],"revision_requests":[]}},"quarantined_references":[]}});
